CREATE DATABASE IF NOT EXISTS business_os;
USE business_os;

CREATE TABLE roles (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(32) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id INT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE customers (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_number VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, email VARCHAR(254), phone VARCHAR(64), address TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, quantity DECIMAL(18,3) NOT NULL DEFAULT 0, unit_price DECIMAL(18,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE invoices (id BIGINT AUTO_INCREMENT PRIMARY KEY, invoice_number VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'OPEN', total DECIMAL(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY, ticket_number VARCHAR(32) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, subject VARCHAR(255) NOT NULL, priority VARCHAR(16) NOT NULL DEFAULT 'NORMAL', status VARCHAR(32) NOT NULL DEFAULT 'OPEN', assigned_user_id BIGINT, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(assigned_user_id) REFERENCES users(id));
CREATE TABLE ticket_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT NOT NULL, user_id BIGINT, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE email_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT, ticket_id BIGINT, invoice_id BIGINT, direction ENUM('INBOUND','OUTBOUND') NOT NULL, sender VARCHAR(254) NOT NULL, recipients TEXT NOT NULL, subject VARCHAR(998) NOT NULL, body MEDIUMTEXT NOT NULL, message_id VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE email_attachments (id BIGINT AUTO_INCREMENT PRIMARY KEY, email_id BIGINT NOT NULL, filename VARCHAR(255) NOT NULL, content_type VARCHAR(128), storage_key VARCHAR(512) NOT NULL, size_bytes BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(email_id) REFERENCES email_messages(id));
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, action VARCHAR(128) NOT NULL, entity_type VARCHAR(64), entity_id BIGINT, details JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
INSERT INTO roles(name) VALUES ('USER'),('ACCOUNTANT'),('MANAGER'),('ADMIN'),('SUPERADMIN') ON DUPLICATE KEY UPDATE name=VALUES(name);
